// 组装 Ollama 提示词
const ctx = $json.data ?? $json;
const plan = ctx.plan ?? {};
const rel = ctx.related_data ?? {};
const trigger = $input.item.json ?? {};
// webhook 的 trigger 信息需要从第一个节点拿
const webhookItems = $('Webhook触发').all();
const wh = webhookItems[0]?.json?.body ?? {};

const triggerTypeMap = {
  data_change: '关联业务数据发生变化',
  leader_feedback: '领导/负责人提出了新的意见',
  manual: '人工发起审查',
};

const relatedSummary = [
  `需求总数：${rel.requirements_total ?? 0}`,
  `最近需求：${(rel.requirements_recent ?? []).map(r => `${r.code} ${r.name}（${r.decision ?? '待评审'}）`).join('；') || '无'}`,
  `处置项总数：${rel.disposals_total ?? 0}`,
  `系统总数：${rel.systems_total ?? 0}`,
  `评分分布：${JSON.stringify(rel.grade_distribution ?? [])}`,
].join('\n');

const userPrompt = `请基于以下信息，对治理方案进行修订分析并输出修改稿。

【触发原因】${triggerTypeMap[wh.trigger_type] ?? wh.trigger_type ?? '未知'}
【触发详情】${wh.detail ?? '无'}

【方案标题】${plan.title ?? ''}
【方案类别】${plan.category ?? ''}

【当前关联业务数据摘要】
${relatedSummary}

【方案全文（Markdown）】
${plan.content_md ?? ''}

要求：
1. 结合触发原因与业务数据，判断方案哪些部分需要调整；
2. suggestion_md 输出【完整修改后的方案 Markdown】，并在开头用「## 修改说明」小节列出你改了什么、为什么；
3. 保持原方案的整体结构与编号体系，只做必要的增量修改，不要重写无关内容；
4. 不确定的地方在「## 待人工确认」小节列出让负责人确认的问题清单；
5. 只输出 JSON 对象，不要输出其他内容。`;

return [{ json: { messages: [
  { role: 'system', content: '你是企业产品组合治理与运营方案专家。你的输出必须是严格的 JSON 对象，包含两个字段：analysis（中文简要分析，200字内）和 suggestion_md（完整修改后的方案 Markdown 文本）。' },
  { role: 'user', content: userPrompt },
] } }];

// 解析模型输出并回传给平台
const resp = $json;
let parsed = {};
try { parsed = JSON.parse(resp.message?.content ?? '{}'); } catch (e) { parsed = { analysis: '模型输出解析失败', suggestion_md: resp.message?.content ?? '' }; }
if (!parsed.suggestion_md) {
  parsed.suggestion_md = parsed.suggestion_md || parsed.analysis || '(模型未返回有效建议)';
}
const webhookItems = $('Webhook触发').all();
const wh = webhookItems[0]?.json?.body ?? {};
const planId = wh.plan_id;
return [{ json: {
  planId,
  payload: {
    trigger_type: wh.trigger_type ?? 'manual',
    trigger_detail: (wh.detail ?? '').slice(0, 2000),
    suggestion_md: parsed.suggestion_md,
    n8n_execution_id: $execution.id,
  },
  owner_email: $('拉取方案上下文').first().json?.data?.plan?.owner_email ?? $('拉取方案上下文').first().json?.plan?.owner_email ?? '',
  plan_title: $('拉取方案上下文').first().json?.data?.plan?.title ?? '',
  analysis: parsed.analysis ?? '',
} }];
